<script setup lang="ts">
/**
 * Forgot Password Page
 *
 * Password reset request form.
 * Generated by Blacksmith. You own this file — customize as needed.
 */
import { reactive, ref } from 'vue'
import type { FormSubmitEvent } from '@nuxt/ui'
import type { z } from 'zod'
import UButton from '@nuxt/ui/components/Button.vue'
import UForm from '@nuxt/ui/components/Form.vue'
import UFormField from '@nuxt/ui/components/FormField.vue'
import UInput from '@nuxt/ui/components/Input.vue'
import { Path } from '@/router/paths'
import TextLink from '@/shared/components/TextLink.vue'
import { useAuth } from '../composables/use-auth'
import { forgotPasswordSchema } from '../schemas'
import AuthPanel from '../components/AuthPanel.vue'

const { sendPasswordResetEmail, error } = useAuth()

const state = reactive({ email: '' })
const submitting = ref(false)
const sent = ref(false)

async function onSubmit(event: FormSubmitEvent<z.output<typeof forgotPasswordSchema>>) {
  submitting.value = true
  try {
    const result = await sendPasswordResetEmail(event.data.email)
    sent.value = result.success
  } finally {
    submitting.value = false
  }
}
</script>

<template>
  <AuthPanel
    title="Reset your password"
    description="Enter your email and we'll send you a reset link."
    :error="error?.message"
    :notice="sent ? 'If an account with that email exists, a reset link has been sent.' : null"
  >
    <UForm
      :schema="forgotPasswordSchema"
      :state="state"
      class="flex flex-col gap-4"
      @submit="onSubmit"
    >
      <UFormField label="Email address" name="email" required>
        <UInput
          v-model="state.email"
          type="email"
          autocomplete="email"
          placeholder="you@example.com"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <UButton
        type="submit"
        size="lg"
        block
        :loading="submitting"
        class="mt-2"
      >
        Send reset link
      </UButton>
    </UForm>

    <template #footer>
      <TextLink :to="Path.Login">
        Back to log in
      </TextLink>
    </template>
  </AuthPanel>
</template>
